      "path": "plugins/dsh-fnos-plugin/src/host/authorized-directories.ts",
      "content": "/** Host routes for fnOS application shared-directory ACLs. */\n\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { constants as fsConstants, createWriteStream, type Stats } from 'node:fs'\nimport { access, mkdir, readdir, realpath, rename, rm, stat, unlink, writeFile } from 'node:fs/promises'\nimport { posix } from 'node:path'\nimport { Writable } from 'node:stream'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport { callFnOsApi, FnOsApiError } from '../api/fnos-api.ts'\nimport {\n  FNOS_AUTHORIZED_CREATE_PATH,\n  FNOS_AUTHORIZED_DELETE_ENTRY_PATH,\n  FNOS_AUTHORIZED_DIRECTORIES_DELETE_PATH,\n  FNOS_AUTHORIZED_DIRECTORIES_PERSIST_PATH,\n  FNOS_AUTHORIZED_ENTRIES_PATH,\n  FNOS_AUTHORIZED_DIRECTORIES_PATH,\n  FNOS_AUTHORIZED_RENAME_ENTRY_PATH,\n  FNOS_PATH_CONVERSION_PATH,\n  FNOS_PATH_OPEN_VALIDATION_PATH,\n  type AuthorizedCreateKind,\n  type AuthorizedCreateRequest,\n  type AuthorizedCreateResponse,\n  type AuthorizedDeleteRequest,\n  type AuthorizedDirectory,\n  type AuthorizedEntry,\n  type AuthorizedEntriesResponse,\n  type AuthorizedRenameRequest,\n  type AuthorizedRenameResponse,\n  type ReadablePath,\n} from '../contracts/authorized-directories-contract.ts'\nimport { FNOS_SETTINGS_DOCUMENT_PATH } from '../contracts/settings-document-contract.ts'\nimport { FNOS_AUTHORIZED_DIRECTORIES_FIELD, type FnosSettings } from '../contracts/theme-contract.ts'\nimport { FNOS_SESSION_LOG_EXPORT_PATH, type FnosSessionLogExportRequest } from '../contracts/session-log-export-contract.ts'\n\nconst BODY_LIMIT = 64 * 1024\n\n/**\n * DSH 自己导出 Session 日志的宿主路由。\n *\n * 官方 `session-log-export` 插件在 `/api` 上注册这条 route，返回 ZIP 流。\n * 这里**不能**改用某个注入服务：本插件早期版本走的是\n * `ctx.get('apiProxy').downloads.sessionLog(...)`，但全仓与上游 DSH 都没有\n * 任何插件提供 `apiProxy`，取值恒为 `undefined`，于是每次「导出到 NAS」都\n * 必然 503。改成回源请求这条真实存在的路由。\n */\nconst DSH_SESSION_LOG_EXPORT_PATH = '/api/session.export'\n\n/** Paths removed during this process must not be reintroduced from a stale env snapshot. */\nconst removedAccessiblePaths = new Set<string>()\n\n/** fnOS supplies user-authorized application paths through this variable. */\nexport const FNOS_ACCESSIBLE_PATHS_ENV = 'TRIM_DATA_ACCESSIBLE_PATHS'\n\n/** fnOS supplies the application's declared shared data paths through this variable. */\nexport const FNOS_DATA_SHARE_PATHS_ENV = 'TRIM_DATA_SHARE_PATHS'\n\ninterface SharedAccessibleFolders {\n  paths?: unknown\n}\n\ninterface SharedAccessibleFolderDeleteResult {\n  suc?: unknown\n}\n\ninterface UserAclEntry {\n  path?: unknown\n  readable?: unknown\n}\n\nexport interface UserAclResult {\n  /** Whether fnOS returned a usable ACL response for the current user. */\n  available: boolean\n  /** Paths that fnOS says the current user can read. */\n  readable: Set<string>\n}\n\n/** Injectable ACL checker used by the path validation tests. */\nexport type UserAclChecker = (\n  req: IncomingMessage | undefined,\n  paths: readonly string[],\n  fallbackRoots?: readonly string[],\n) => Promise<UserAclResult>\n\nexport interface PathValidationOptions {\n  /** Override the application roots when validating in isolation. */\n  roots?: readonly string[]\n  /** Override the current-user ACL lookup when validating in isolation. */\n  checkUserAcl?: UserAclChecker\n}\n\nexport type PathValidationFailure =\n  | 'fnos-path-not-authorized'\n  | 'fnos-path-not-found'\n  | 'fnos-path-not-readable'\n  | 'fnos-user-permission-denied'\n  | 'fnos-user-permission-unavailable'\n\nexport interface PathValidationResult {\n  ok: boolean\n  failure?: PathValidationFailure\n}\n\ninterface ConvertedPath {\n  path?: unknown\n  semanticPath?: unknown\n}\n\ninterface ConvertedPaths {\n  status?: unknown\n  result?: unknown\n}\n\ninterface ConvertedPathsEnvelope {\n  data?: unknown\n  result?: unknown\n}\n\nconst AUTHORIZED_ENTRIES_LIMIT = 500\n\nclass AuthorizedEntriesError extends Error {\n  constructor(readonly code: string, readonly status: number, message = code) {\n    super(message)\n    this.name = 'AuthorizedEntriesError'\n  }\n}\n\nfunction header(req: IncomingMessage, name: string): string | undefined {\n  const value = req.headers[name]\n  return Array.isArray(value) ? value[0] : value\n}\n\n/**\n * Read the user identity supplied by the fnOS unified gateway.\n *\n * `TRIM_UID` is the application service user and must not be used here. The\n * current browser user is carried by `X-Trim-Userid` on gateway requests.\n */\nexport function gatewayUserId(req: IncomingMessage | undefined): number | undefined {\n  const value = req === undefined ? undefined : header(req, 'x-trim-userid')?.trim()\n  if (value === undefined || !/^\\d+$/u.test(value)) return undefined\n  const uid = Number(value)\n  return Number.isSafeInteger(uid) && uid >= 0 ? uid : undefined\n}\n\n/**\n * The authority this request was actually delivered to, as the fnOS gateway\n * rewrote it.\n *\n * `x-forwarded-*` is deliberately ignored here. The gateway never sets those\n * headers—it rewrites `host` and `origin` to the loopback authority instead\n * (`packages/fnos-gateway/src/middleware/request-headers.ts`), precisely so\n * strict same-origin plugin routes stay valid. Trusting a forwarded host would\n * compare two values of different provenance: the Origin arrives rewritten to\n * loopback while `x-forwarded-host` (injected by the platform proxy, or by any\n * intermediary that can add a header) still names the public domain. They can\n * never be equal, so every remote request failed with 403.\n *\n * Reading only `host` makes both sides of the comparison come from the same\n * rewrite, and keeps the decision out of reach of request-supplied headers.\n */\nfunction requestOrigin(req: IncomingMessage): string | undefined {\n  const host = header(req, 'host')\n  if (host === undefined) return undefined\n  // The gateway hop is plain loopback, so scheme comes from the socket itself.\n  const proto = (req.socket as IncomingMessage['socket'] & { encrypted?: boolean }).encrypted === true ? 'https' : 'http'\n  try {\n    return new URL(`${proto}://${host}`).origin\n  } catch {\n    return undefined\n  }\n}\n\nfunction normalizeOrigin(raw: string): string | undefined {\n  try {\n    return new URL(raw).origin\n  } catch {\n    return undefined\n  }\n}\n\nfunction localPeer(req: IncomingMessage): boolean {\n  const remote = req.socket.remoteAddress\n  return remote === '127.0.0.1' || remote === '::1' || remote === '::ffff:127.0.0.1'\n}\n\n/**\n * Accept the NAS gateway's same-origin requests, but reject cross-site calls.\n *\n * Three independent rejections, strongest signal first:\n * 1. `sec-fetch-site: cross-site` — set by the browser, not forgeable by page\n *    scripts; rejected before anything else is considered.\n * 2. An `Origin` that disagrees with the delivered authority — catches a page\n *    on another site issuing a credentialed request.\n * 3. No `Origin` at all from a non-loopback peer — a same-origin browser request\n *    always carries one, so its absence means a non-browser client.\n *\n * The comparison is only meaningful because both sides read the same rewritten\n * `host`; see {@link requestOrigin}.\n */\nexport function isTrustedFnosRequest(req: IncomingMessage): boolean {\n  const fetchSite = header(req, 'sec-fetch-site')?.trim().toLowerCase()\n  if (fetchSite === 'cross-site') return false\n  const origin = header(req, 'origin')\n  if (origin !== undefined) return requestOrigin(req) === normalizeOrigin(origin)\n  return localPeer(req)\n}\n\nfunction json(res: ServerResponse, status: number, value: unknown): void {\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'cache-control': 'no-store',\n    'x-content-type-options': 'nosniff',\n  })\n  res.end(JSON.stringify(value))\n}\n\nfunction readJsonBody(req: IncomingMessage): Promise<unknown> {\n  return new Promise((resolve, reject) => {\n    let body = ''\n    let size = 0\n    let finished = false\n    req.setEncoding('utf8')\n    req.on('data', (chunk: string) => {\n      if (finished) return\n      size += Buffer.byteLength(chunk)\n      if (size > BODY_LIMIT) {\n        finished = true\n        reject(new Error('request body is too large'))\n        return\n      }\n      body += chunk\n    })\n    req.on('end', () => {\n      if (finished) return\n      finished = true\n      try {\n        resolve(JSON.parse(body) as unknown)\n      } catch {\n        reject(new Error('request body is not valid JSON'))\n      }\n    })\n    req.on('error', error => {\n      if (finished) return\n      finished = true\n      reject(error)\n    })\n  })\n}\n\n/** Normalize one fnOS volume path for display and exact delete matching. */\nexport function normalizeAuthorizedPath(value: unknown): string | undefined {\n  if (typeof value !== 'string') return undefined\n  const path = value.trim()\n  if (path.length === 0 || !path.startsWith('/') || path.includes('\\0')) return undefined\n  if (path === '/') return path\n  return path.replace(/\\/+$/u, '')\n}\n\n/** Normalize a path used for the open authorization boundary. */\nexport function normalizePathForAuthorization(value: unknown): string | undefined {\n  const path = normalizeAuthorizedPath(value)\n  if (path === undefined) return undefined\n  return normalizeAuthorizedPath(posix.normalize(path))\n}\n\n/** Check a target path against authorized roots without confusing path prefixes. */\nexport function isPathWithinAuthorizedDirectory(pathValue: unknown, rootsValue: unknown): boolean {\n  const path = normalizePathForAuthorization(pathValue)\n  if (path === undefined) return false\n  const roots = normalizeAuthorizedPaths(rootsValue).map(normalizePathForAuthorization).filter(\n    (root): root is string => root !== undefined,\n  )\n  return roots.some(root => root === '/' || path === root || path.startsWith(`${root}/`))\n}\n\n/** Keep API order while removing malformed and duplicate paths. */\nexport function normalizeAuthorizedPaths(value: unknown): string[] {\n  if (!Array.isArray(value)) return []\n  const paths: string[] = []\n  const seen = new Set<string>()\n  for (const entry of value) {\n    const path = normalizeAuthorizedPath(entry)\n    if (path === undefined || seen.has(path)) continue\n    seen.add(path)\n    paths.push(path)\n  }\n  return paths\n}\n\nfunction userAclEntries(value: unknown): UserAclEntry[] {\n  if (Array.isArray(value)) return value.filter(\n    (entry): entry is UserAclEntry => typeof entry === 'object' && entry !== null && !Array.isArray(entry),\n  )\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return []\n  const record = value as Record<string, unknown>\n  for (const key of ['result', 'paths', 'data']) {\n    const entries = userAclEntries(record[key])\n    if (entries.length > 0) return entries\n  }\n  return []\n}\n\nfunction userAclResult(value: unknown): UserAclResult {\n  const readable = new Set<string>()\n  for (const entry of userAclEntries(value)) {\n    if (entry.readable !== true) continue\n    const path = normalizePathForAuthorization(entry.path)\n    if (path !== undefined) readable.add(path)\n  }\n  return { available: true, readable }\n}\n\n/**\n * Check the current gateway user instead of treating an application ACL root\n * as proof that every user can read every child path.\n *\n * Direct localhost development requests do not carry a NAS user header. In\n * that case the real process-level fs check remains the only meaningful check\n * and the fnOS `openFile()` bridge is still the final host-side operation.\n */\nexport const checkCurrentUserAcl: UserAclChecker = async (req, paths, fallbackRoots = []) => {\n  const uid = gatewayUserId(req)\n  const normalizedPaths = normalizeAuthorizedPaths(paths)\n  if (uid === undefined || normalizedPaths.length === 0) {\n    return { available: true, readable: new Set(normalizedPaths) }\n  }\n  try {\n    const data = await callFnOsApi<unknown>('trim.file.checkUserACL', {\n      uid,\n      path: normalizedPaths.length === 1 ? normalizedPaths[0] : normalizedPaths,\n    })\n    return userAclResult(data)\n  } catch (error: unknown) {\n    console.warn('[dsh-fnos] unable to check current fnOS user ACL', error)\n    // The fnOS runtime already supplies the paths visible to the application\n    // through its environment. This is also the source used by the workspace\n    // card when the shared-access API is unavailable. Keep the picker usable\n    // during that same degraded state, but retain the application root and\n    // filesystem checks instead of treating every path as readable.\n    const declaredRoots = mergeAuthorizedPaths(\n      fallbackRoots,\n      accessiblePathsFromEnvironment(),\n      dataSharePathsFromEnvironment(),\n      defaultApplicationPathsFromEnvironment(),\n    )\n    if (declaredRoots.length > 0) {\n      const readable = normalizedPaths.filter(path => isPathWithinAuthorizedDirectory(path, declaredRoots))\n      console.warn('[dsh-fnos] using fnOS declared paths because the current-user ACL query failed')\n      return { available: true, readable: new Set(readable) }\n    }\n    return { available: false, readable: new Set() }\n  }\n}\n\n/** Parse a fnOS colon-separated path environment variable. */\nexport function splitPathEnvironment(value: unknown): string[] {\n  if (typeof value !== 'string') return []\n  return value.split(':').map(value => value.trim()).filter(value => value.length > 0)\n}\n\n/** Read user-authorized paths from the lifecycle environment and de-duplicate them. */\nexport function accessiblePathsFromEnvironment(env: NodeJS.ProcessEnv = process.env): string[] {\n  return normalizeAuthorizedPaths(splitPathEnvironment(env[FNOS_ACCESSIBLE_PATHS_ENV]))\n}\n\n/** Read declared application data shares for display and de-duplicate them. */\nexport function dataSharePathsFromEnvironment(env: NodeJS.ProcessEnv = process.env): string[] {\n  return normalizeAuthorizedPaths(splitPathEnvironment(env[FNOS_DATA_SHARE_PATHS_ENV]))\n}\n\n/**\n * Resolve the fnOS application-owned data paths for this app. The @app\n * installation directory is intentionally excluded: it is an application\n * implementation path, not a user-facing authorization root. The remaining\n * app-managed data paths are read-only defaults, just like @appshare, and do\n * not depend on a user selecting them through the ACL management card first.\n */\nexport function defaultApplicationPathsFromEnvironment(env: NodeJS.ProcessEnv = process.env): string[] {\n  const appName = (env.TRIM_APPNAME ?? env.APPNAME ?? 'fn-deepseek-harness').trim() || 'fn-deepseek-harness'\n  const candidates: string[] = [env.TRIM_PKGHOME].filter((value): value is string => typeof value === 'string')\n  let volume = typeof env.TRIM_APPDEST_VOL === 'string' ? env.TRIM_APPDEST_VOL.trim().replace(/\\/+$/u, '') : ''\n  const knownPath = [env.TRIM_APPDEST, ...candidates]\n    .filter((value): value is string => typeof value === 'string')\n    .find(value => /^\\/[^/]+\\/@app(?:center|home|share|data|conf)?\\/[^/]+$/u.test(value))\n  if (volume.length === 0 && knownPath !== undefined) volume = knownPath.slice(0, knownPath.indexOf('/@app'))\n  if (volume.length > 0) {\n    for (const prefix of ['@apphome', '@appshare', '@appdata', '@appconf']) {\n      candidates.push(`${volume}/${prefix}/${appName}`)\n    }\n  }\n  return normalizeAuthorizedPaths(candidates)\n}\n\n/** Combine path sources without changing the first-seen order. */\nexport function mergeAuthorizedPaths(...values: unknown[]): string[] {\n  return normalizeAuthorizedPaths(values.flatMap(value => Array.isArray(value) ? value : splitPathEnvironment(value)))\n}\n\n/** Keep a just-removed ACL out of the process-local merged configuration. */\nexport function markAuthorizedPathRemoved(value: unknown): void {\n  const path = normalizeAuthorizedPath(value)\n  if (path !== undefined) removedAccessiblePaths.add(path)\n}\n\nfunction requestLanguage(req: IncomingMessage): string {\n  const value = header(req, 'accept-language')?.split(',')[0]?.trim().replace(/_/gu, '-')\n  if (value !== undefined && /^[A-Za-z]{2,3}(?:-[A-Za-z0-9]{2,8})?$/u.test(value)) return value\n  return 'en-US'\n}\n\nexport function readableFallbackPath(path: string, language: string): string {\n  const volume = /^\\/vol(\\d+)(?:\\/(.*))?$/u.exec(path)\n  if (volume !== null) {\n    const prefix = language.toLowerCase().startsWith('zh') ? `存储空间${volume[1]}` : `Storage ${volume[1]}`\n    return volume[2] === undefined || volume[2].length === 0 ? prefix : `${prefix}/${volume[2]}`\n  }\n  if (path === '/') return language.toLowerCase().startsWith('zh') ? '根目录' : 'Root'\n  return path\n}\n\nfunction convertedPathMap(value: unknown): Map<string, string> {\n  const result = new Map<string, string>()\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return result\n  const envelope = value as ConvertedPathsEnvelope\n  const nested = typeof envelope.data === 'object' && envelope.data !== null && !Array.isArray(envelope.data)\n    ? envelope.data as ConvertedPaths\n    : undefined\n  const entries = Array.isArray(envelope.result) ? envelope.result : nested?.result\n  if (!Array.isArray(entries)) return result\n  for (const entry of entries) {\n    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) continue\n    const path = normalizeAuthorizedPath((entry as ConvertedPath).path)\n    const rawSemanticPath = (entry as ConvertedPath).semanticPath\n    const semanticPath = typeof rawSemanticPath === 'string' ? rawSemanticPath.trim() : ''\n    // A few older fnOS builds echo the internal path when the path scope is\n    // missing. Do not treat that echo as a successful human-readable value.\n    if (path !== undefined && semanticPath.length > 0 && semanticPath !== path) result.set(path, semanticPath)\n  }\n  return result\n}\n\n/** Pair internal paths with fnOS semantic paths, falling back per entry. */\nexport async function convertPathsForDisplay(pathsValue: unknown, language = 'en-US'): Promise<ReadablePath[]> {\n  const paths = normalizeAuthorizedPaths(pathsValue)\n  if (paths.length === 0) return []\n\n  let convertedValue: unknown\n  try {\n    convertedValue = await callFnOsApi<ConvertedPaths>('trim.file.convertPath', {\n      path: paths,\n      language,\n    })\n  } catch (error: unknown) {\n    // Keep file/dir insertion usable on older fnOS versions that do not expose\n    // path conversion. The client can still retain the internal path safely.\n    console.warn('[dsh-fnos] unable to convert selected fnOS paths', error)\n  }\n\n  const converted = convertedPathMap(convertedValue)\n  return paths.map(path => ({\n    path,\n    semanticPath: converted.get(path) ?? readableFallbackPath(path, language),\n  }))\n}\n\n/** Pair normalized internal paths with their fnOS user-facing semantic paths. */\nexport function buildAuthorizedDirectories(\n  pathsValue: unknown,\n  convertedValue: unknown,\n  language = 'en-US',\n  readOnlyPathsValue: unknown = [],\n): AuthorizedDirectory[] {\n  const paths = normalizeAuthorizedPaths(pathsValue)\n  const readOnlyPaths = new Set(normalizeAuthorizedPaths(readOnlyPathsValue))\n  const converted = convertedPathMap(convertedValue)\n  return paths.map(path => ({\n    path,\n    semanticPath: converted.get(path) ?? readableFallbackPath(path, language),\n    removable: !readOnlyPaths.has(path),\n  }))\n}\n\n/**\n * Query the current ACL. The environment is a fallback for hosts that expose\n * the ACL to the app process but temporarily reject the read API; a successful\n * API response remains authoritative so a just-removed path is not resurrected\n * from a stale process environment.\n */\nexport async function loadAuthorizedDirectoryPaths(): Promise<string[]> {\n  const environmentPaths = accessiblePathsFromEnvironment()\n  try {\n    const data = await callFnOsApi<SharedAccessibleFolders>('trim.file.getSharedAccessibleFolders')\n    const apiPaths = normalizeAuthorizedPaths(data?.paths)\n    for (const path of apiPaths) removedAccessiblePaths.delete(path)\n    return mergeAuthorizedPaths(apiPaths, environmentPaths).filter(path => !removedAccessiblePaths.has(path))\n  } catch (error: unknown) {\n    if (environmentPaths.length === 0) throw error\n    console.warn('[dsh-fnos] using TRIM_DATA_ACCESSIBLE_PATHS because the fnOS ACL query failed')\n    return environmentPaths.filter(path => !removedAccessiblePaths.has(path))\n  }\n}\n\n/**\n * 查询**当前用户**授权给本应用的目录（FNOS-009-10）。\n *\n * 与 `authorizeUserFile` 的关键区别：这是后端查询接口，**不弹确认框、不等\n * 用户操作**。官方文档把 `authorizeUserFile` 定义为「按已知路径重新申请\n * 授权」，调用会给用户弹出「申请访问以下文件」；用它做校验会让每次刷新\n * 列表都弹框，且返回值表达的是「这次申请的结果」而不是「当前是否仍有权限」。\n *\n * `uid` 是该接口的**必填**参数，指当前使用用户（浏览器用户），取自 fnOS 统一\n * 网关注入的 `X-Trim-Userid`。不要用 `TRIM_UID`——那是应用服务账号。\n *\n * @param uid - 当前用户 UID；缺失时无法查询。\n * @returns 用户授权目录；uid 缺失或查询失败时返回 `undefined`——表示**无法判定**，\n * 调用方必须保留目录而不是判为失效。\n */\nexport async function loadUserAuthorizedDirectoryPaths(uid: number | undefined): Promise<string[] | undefined> {\n  if (uid === undefined) {\n    console.warn('[dsh-fnos] no gateway user id; keeping every persisted entry')\n    return undefined\n  }\n  try {\n    const data = await callFnOsApi<SharedAccessibleFolders>('trim.file.getUserAccessibleFolders', { uid })\n    return normalizeAuthorizedPaths(data?.paths)\n  } catch (error: unknown) {\n    console.warn('[dsh-fnos] unable to query user-authorized directories; keeping every persisted entry', error)\n    return undefined\n  }\n}\n\nasync function readablePathStat(path: string): Promise<Stats | undefined> {\n  try {\n    const pathStat = await stat(path)\n    const mode = pathStat.isDirectory() ? fsConstants.R_OK | fsConstants.X_OK : fsConstants.R_OK\n    await access(path, mode)\n    return pathStat\n  } catch {\n    return undefined\n  }\n}\n\nasync function existingAuthorizedRoots(rootsValue: unknown): Promise<string[]> {\n  const roots = normalizeAuthorizedPaths(rootsValue)\n  const resolved = await Promise.all(roots.map(async root => {\n    try {\n      const resolvedRoot = normalizePathForAuthorization(await realpath(root))\n      if (resolvedRoot === undefined) return undefined\n      const rootStat = await readablePathStat(resolvedRoot)\n      return rootStat?.isDirectory() === true ? resolvedRoot : undefined\n    } catch {\n      return undefined\n    }\n  }))\n  return resolved.filter((root): root is string => root !== undefined)\n}\n\nasync function currentAuthorizedRoots(options: PathValidationOptions = {}): Promise<string[]> {\n  if (options.roots !== undefined) return existingAuthorizedRoots(options.roots)\n  return resolvedAuthorizedRoots()\n}\n\nasync function validateReadableAuthorizedPath(\n  req: IncomingMessage | undefined,\n  path: string,\n  roots: readonly string[],\n  checkUserAcl: UserAclChecker,\n): Promise<PathValidationResult> {\n  let pathStat: Stats\n  try {\n    pathStat = await stat(path)\n  } catch {\n    return { ok: false, failure: 'fnos-path-not-found' }\n  }\n  try {\n    const mode = pathStat.isDirectory() ? fsConstants.R_OK | fsConstants.X_OK : fsConstants.R_OK\n    await access(path, mode)\n  } catch {\n    return { ok: false, failure: 'fnos-path-not-readable' }\n  }\n  if (!await isResolvedPathWithinAuthorizedRoots(path, roots)) {\n    return { ok: false, failure: 'fnos-path-not-authorized' }\n  }\n\n  const userAcl = await checkUserAcl(req, [path], roots)\n  if (!userAcl.available) return { ok: false, failure: 'fnos-user-permission-unavailable' }\n  if (!userAcl.readable.has(path)) return { ok: false, failure: 'fnos-user-permission-denied' }\n  return { ok: true }\n}\n\n/**\n * Validate a DSH file/directory target using all applicable permission layers:\n * the app's real shared roots, the process's actual fs access, and the\n * current NAS user ACL supplied by the unified gateway.\n */\nexport async function validatePathForOpen(\n  pathValue: unknown,\n  req?: IncomingMessage,\n  options: PathValidationOptions = {},\n): Promise<PathValidationResult> {\n  const path = normalizePathForAuthorization(pathValue)\n  if (path === undefined) return { ok: false, failure: 'fnos-path-not-authorized' }\n  const roots = await currentAuthorizedRoots(options)\n  return validateReadableAuthorizedPath(req, path, roots, options.checkUserAcl ?? checkCurrentUserAcl)\n}\n\n/** Backward-compatible boolean helper for callers that only need a verdict. */\nexport async function isAuthorizedPathForOpen(\n  pathValue: unknown,\n  req?: IncomingMessage,\n): Promise<boolean> {\n  return (await validatePathForOpen(pathValue, req)).ok\n}\n\nasync function convertDirectories(paths: string[], language: string, readOnlyPaths: string[] = []): Promise<AuthorizedDirectory[]> {\n  const readOnly = new Set(normalizeAuthorizedPaths(readOnlyPaths))\n  const converted = await convertPathsForDisplay(paths, language)\n  return converted.map(entry => ({ ...entry, removable: !readOnly.has(entry.path) }))\n}\n\n/**\n * 给每个**可移除**目录标注它是否仍在 fnOS 的授权范围内（FNOS-009-10）。\n *\n * 判定依据是两个**无交互**查询接口的返回集合：\n *\n * - `trim.file.getSharedAccessibleFolders`（管理员授权给应用的路径）\n * - `trim.file.getUserAccessibleFolders`（当前用户授权给应用的路径）\n *\n * 只读的应用共享路径不参与判定：它们由 fnOS 声明，不属于用户授权，标注\n * `valid` 没有意义。\n *\n * 集合来源不可用时（查询接口抛错）该目录的 `valid` 保持 `undefined`，表示\n * 「无法判定」。调用方必须保留这类目录——把「问不到」当成「没权限」会删掉\n * 用户的有效授权记录。\n *\n * @param directories - 已组装好的展示列表。\n * @param knownPaths - 两个查询接口合并出的有效路径集合；`undefined` 表示无法判定。\n * @returns 标注了 `valid` 的新列表。\n */\nexport function markAuthorizedDirectoryValidity(\n  directories: AuthorizedDirectory[],\n  knownPaths: readonly string[] | undefined,\n): AuthorizedDirectory[] {\n  if (knownPaths === undefined) return directories\n  const known = new Set(knownPaths)\n  return directories.map(directory => directory.removable\n    ? { ...directory, valid: known.has(directory.path) }\n    : directory)\n}\n\n/**\n * 持久化列表的读写入口。\n *\n * settings 是权威来源：这里的三个函数只负责在它与列表展示之间搬运数据，\n * 不建立第二份镜像文件——目录列表是纯插件侧数据，settings 已经提供原子写与\n * 升级保留，再加一层镜像只会多一个可能与权威源不一致的地方。\n */\nexport interface AuthorizedDirectoriesSettings {\n  describe(): { ns: string, value: unknown }[]\n  update(ns: string, patch: Record<string, unknown>): Promise<void>\n}\n\n/** 读取持久化的授权目录列表；字段缺失或非法时返回空列表。 */\nexport function readPersistedAuthorizedDirectories(settings: AuthorizedDirectoriesSettings, namespace: string): string[] {\n  const descriptor = settings.describe().find(row => row.ns === namespace)\n  const value = descriptor?.value as FnosSettings | undefined\n  return normalizeAuthorizedPaths(value?.[FNOS_AUTHORIZED_DIRECTORIES_FIELD])\n}\n\n/** 写入持久化列表；保持首次出现顺序并去重。 */\nexport async function writePersistedAuthorizedDirectories(\n  settings: AuthorizedDirectoriesSettings,\n  namespace: string,\n  pathsValue: unknown,\n): Promise<string[]> {\n  const paths = normalizeAuthorizedPaths(pathsValue)\n  await settings.update(namespace, { [FNOS_AUTHORIZED_DIRECTORIES_FIELD]: paths })\n  return paths\n}\n\n/**\n * 合并持久化列表与实时来源。\n *\n * 持久化项优先展示：实时查询失败时它们仍要出现在列表里（FNOS-009-09-AC-02）。\n * 实时来源里新增的路径照常合入展示，但不自动写入持久化——共享应用路径等\n * 只读项由 `readOnlyPaths` 承载。\n */\nexport function mergePersistedWithLive(\n  persistedValue: unknown,\n  liveValue: unknown,\n  readOnlyValue: unknown = [],\n): string[] {\n  return mergeAuthorizedPaths(persistedValue, liveValue, readOnlyValue)\n}\n\nexport async function loadAuthorizedDirectories(req: IncomingMessage): Promise<AuthorizedDirectory[]> {\n  const readOnlyPaths = mergeAuthorizedPaths(dataSharePathsFromEnvironment(), defaultApplicationPathsFromEnvironment())\n  let accessiblePaths: string[] = []\n  try {\n    accessiblePaths = await loadAuthorizedDirectoryPaths()\n  } catch (error: unknown) {\n    // The declared app share remains useful even when an older host does not\n    // expose the live ACL query. Keep that display-only source available.\n    if (readOnlyPaths.length === 0) throw error\n    console.warn('[dsh-fnos] using TRIM_DATA_SHARE_PATHS because the fnOS ACL query failed', error)\n  }\n  // Keep configured shared paths visible in the management card even when a\n  // volume is temporarily offline. Functional browsing/opening below still\n  // requires the path to exist and be readable at the time of use.\n  const paths = mergeAuthorizedPaths(accessiblePaths, readOnlyPaths)\n  return convertDirectories(paths, requestLanguage(req), readOnlyPaths)\n}\n\n/**\n * 列表展示的合并入口：持久化列表优先，其次实时查询与只读共享路径。\n *\n * 与 `loadAuthorizedDirectories` 的区别是它接收已取到的实时结果，便于在\n * 实时查询失败时只回退到持久化列表，而不是让整页报错（FNOS-009-09-AC-02）。\n */\nexport async function loadAuthorizedDirectoriesWithPersisted(\n  req: IncomingMessage,\n  persistedValue: unknown,\n  livePathsValue?: unknown,\n): Promise<AuthorizedDirectory[]> {\n  const readOnlyPaths = mergeAuthorizedPaths(dataSharePathsFromEnvironment(), defaultApplicationPathsFromEnvironment())\n  const persisted = normalizeAuthorizedPaths(persistedValue)\n  let livePaths: string[]\n  if (livePathsValue === undefined) {\n    try {\n      livePaths = await loadAuthorizedDirectoryPaths()\n    } catch (error: unknown) {\n      if (persisted.length === 0 && readOnlyPaths.length === 0) throw error\n      console.warn('[dsh-fnos] showing the persisted authorized directories because the fnOS ACL query failed', error)\n      livePaths = []\n    }\n  } else {\n    livePaths = normalizeAuthorizedPaths(livePathsValue)\n  }\n  const paths = mergePersistedWithLive(persisted, livePaths, readOnlyPaths)\n  return convertDirectories(paths, requestLanguage(req), readOnlyPaths)\n}\n\n/**\n * 合并两个无交互查询接口的结果，得到「当前有效路径」集合。\n *\n * 任一接口失败时整体返回 `undefined`：此时无法区分「没权限」与「问不到」，\n * 调用方必须跳过剔除。\n */\nasync function knownAuthorizedPaths(req: IncomingMessage): Promise<string[] | undefined> {\n  const [shared, user] = await Promise.all([\n    loadAuthorizedDirectoryPaths(),\n    loadUserAuthorizedDirectoryPaths(gatewayUserId(req)),\n  ])\n  if (user === undefined) return undefined\n  return mergeAuthorizedPaths(shared, user)\n}\n\nfunction errorResponse(res: ServerResponse, error: unknown): void {\n  if (error instanceof FnOsApiError && error.apiCode === 1) {\n    json(res, 403, { error: 'fnos-authorized-directory-permission-denied' })\n    return\n  }\n  json(res, 502, { error: 'fnos-authorized-directory-request-failed' })\n}\n\nfunction deletePath(value: unknown): string | undefined {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined\n  return normalizeAuthorizedPath((value as Record<string, unknown>).path)\n}\n\nfunction conversionPaths(value: unknown): string[] | undefined {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined\n  const valuePaths = (value as Record<string, unknown>).paths\n  if (!Array.isArray(valuePaths)) return undefined\n  return normalizeAuthorizedPaths(valuePaths)\n}\n\nfunction openPathValue(value: unknown): string | undefined {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined\n  return normalizePathForAuthorization((value as Record<string, unknown>).path)\n}\n\nfunction sessionLogExportRequest(value: unknown): FnosSessionLogExportRequest | undefined {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined\n  const record = value as Record<string, unknown>\n  const sessionId = typeof record.sessionId === 'string' && record.sessionId.length > 0 && record.sessionId.length <= 256\n    ? record.sessionId\n    : undefined\n  const directory = normalizePathForAuthorization(record.directory)\n  return sessionId === undefined || directory === undefined ? undefined : { sessionId, directory }\n}\n\nfunction sessionLogExportFilename(sessionId: string): string {\n  const safeId = sessionId.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120) || 'session'\n  return `dsh-session-${safeId}-${Date.now()}.zip`\n}\n\n/**\n * 回源拉取 DSH 自己导出的 Session 日志 ZIP。\n *\n * 请求打到本机 webServer 的 loopback 地址：官方 `session-log-export` 通过\n * `connection.fetch.register('/api/session.export')` 把 route 挂在 DSH 自己的\n * `/api` 上，宿主直接请求它比在本插件里重做 flush/打包/附件收集安全得多。\n *\n * 鉴权：`/api` 的信任判定放行 loopback（`isTrustedApiRequest` 对 loopback\n * Host 直接返回 true），但 browser-session 认证仍然需要 `dsh-auth-*` Cookie。\n * 因此把当前浏览器请求的 Cookie 原样转发给 loopback 上的 DSH；不能误以为\n * loopback 同时绕过了 browser-session 校验。\n *\n * @param ctx - 提供 webServer 的宿主上下文，用于取本机监听地址。\n * @param sessionId - 目标会话。\n * @param signal - 调用方中止信号，客户端断开时一并取消上游请求。\n * @param cookie - 当前浏览器请求的 Cookie，供 DSH browser-session 认证。\n */\nexport async function fetchSessionLogZip(\n  ctx: Context,\n  sessionId: string,\n  signal: AbortSignal,\n  cookie: string | undefined,\n): Promise<Response> {\n  const { host, port } = ctx.webServer\n  // 绑定 0.0.0.0 时仍走 loopback：本机请求不需要经过对外网卡。\n  const address = host === '0.0.0.0' ? '127.0.0.1' : host\n  const url = new URL(DSH_SESSION_LOG_EXPORT_PATH, `http://${address}:${String(port)}`)\n  url.searchParams.set('sessionId', sessionId)\n  url.searchParams.set('includeDescendants', 'true')\n  const headers = cookie === undefined ? undefined : { cookie }\n  return fetch(url, { method: 'GET', ...(headers === undefined ? {} : { headers }), signal })\n}\n\nasync function writeSessionLogResponse(response: Response, target: string, signal: AbortSignal): Promise<void> {\n  if (!response.ok || response.body === null) {\n    throw new Error(`session log export returned HTTP ${response.status}`)\n  }\n  const stream = createWriteStream(target, { flags: 'wx', mode: 0o600 })\n  let completed = false\n  try {\n    await response.body.pipeTo(Writable.toWeb(stream), { signal })\n    completed = true\n  } finally {\n    if (!completed) {\n      stream.destroy()\n      await unlink(target).catch(() => undefined)\n    }\n  }\n}\n\n/** Read the optional directory field used by the authorized-entry listing. */\nfunction listingPathValue(value: unknown): string | undefined | null {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null\n  const raw = (value as Record<string, unknown>).path\n  if (raw === undefined) return undefined\n  return normalizePathForAuthorization(raw) ?? null\n}\n\n/**\n * 校验「新建条目」的请求体（FNOS-034）。\n *\n * 命名规则刻意保守：只允许**单段**名字，不接受任何路径分隔符，因此客户端\n * 无法用 `../` 或绝对路径把条目写到父目录之外。Host 侧随后还会独立校验父\n * 目录是否落在授权根内，两层互不依赖。\n *\n * 拒绝的字符是 Windows 与 fnOS 共享目录共有的禁名（`:` `*` `?` `\"` `<` `>`\n * `|` 与控制字符）：NAS 上的共享目录常被 SMB 客户端访问，允许这些字符会造出\n * 在其它协议下打不开的条目。\n */\nexport function parseCreateRequest(value: unknown): AuthorizedCreateRequest | null {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null\n  const record = value as Record<string, unknown>\n  const parent = normalizePathForAuthorization(record.parent)\n  if (parent === undefined) return null\n  const kind = record.kind\n  if (kind !== 'directory' && kind !== 'file') return null\n  const name = parseEntryName(record.name)\n  return name === null ? null : { parent, name, kind }\n}\n\n/**\n * 校验单段条目名（新建与重命名共用）。\n *\n * 规则刻意保守：只允许**单段**名字，不接受任何路径分隔符，因此客户端无法用\n * `../` 或绝对路径把条目挪到父目录之外。Host 侧随后还会独立校验落点是否在\n * 授权根内，两层互不依赖。\n *\n * 拒绝的字符是 Windows 与 fnOS 共享目录共有的禁名（`:` `*` `?` `\"` `<` `>`\n * `|` 与控制字符）：NAS 上的共享目录常被 SMB 客户端访问，允许这些字符会造出\n * 在其它协议下打不开的条目。\n */\nfunction parseEntryName(value: unknown): string | null {\n  if (typeof value !== 'string') return null\n  const name = value.trim()\n  if (name.length === 0 || name.length > 255) return null\n  // 单段名字：不含分隔符与控制字符，也不是 . 或 ..\n  if (name === '.' || name === '..') return null\n  if (/[/\\\\:*?\"<>|]/u.test(name)) return null\n  // 控制字符单独判定：直接把它写进字符类会触发 `no-control-regex`，\n  // 而这里的目的恰恰是拒绝它们，用码点比较更直白也不会误伤可打印字符。\n  for (const character of name) {\n    if (character.codePointAt(0)! < 0x20) return null\n  }\n  return name\n}\n\n/**\n * 校验「删除条目」的请求体。\n *\n * 只接受绝对路径；真正的边界判定交给路由里的授权校验。这里不猜路径含义，\n * 避免把「相对路径」这类输入误当成合法目标。\n */\nexport function parseDeleteRequest(value: unknown): AuthorizedDeleteRequest | null {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null\n  const path = normalizePathForAuthorization((value as Record<string, unknown>).path)\n  return path === undefined ? null : { path }\n}\n\n/**\n * 校验「重命名条目」的请求体。\n *\n * 路径与名字分别校验：路径只负责指向目标（边界由路由判定），名字必须是合法\n * 单段名。两者都不在此处猜测语义，避免把越权输入当成合法目标放行。\n */\nexport function parseRenameRequest(value: unknown): AuthorizedRenameRequest | null {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null\n  const record = value as Record<string, unknown>\n  const path = normalizePathForAuthorization(record.path)\n  if (path === undefined) return null\n  const name = parseEntryName(record.name)\n  return name === null ? null : { path, name }\n}\n\nasync function resolvedAuthorizedRoots(): Promise<string[]> {\n  let roots: string[]\n  try {\n    roots = mergeAuthorizedPaths(await loadAuthorizedDirectoryPaths(), dataSharePathsFromEnvironment(), defaultApplicationPathsFromEnvironment())\n  } catch (error: unknown) {\n    const shares = mergeAuthorizedPaths(dataSharePathsFromEnvironment(), defaultApplicationPathsFromEnvironment())\n    if (shares.length === 0) throw error\n    roots = shares\n  }\n  return existingAuthorizedRoots(roots)\n}\n\nasync function isResolvedPathWithinAuthorizedRoots(path: string, roots: readonly string[]): Promise<boolean> {\n  try {\n    const resolvedPath = normalizePathForAuthorization(await realpath(path))\n    if (resolvedPath === undefined) return false\n    return roots.some(root => root === '/' || resolvedPath === root || resolvedPath.startsWith(`${root}/`))\n  } catch {\n    return false\n  }\n}\n\nfunction authorizedEntriesErrorForValidation(result: PathValidationResult): AuthorizedEntriesError {\n  switch (result.failure) {\n    case 'fnos-path-not-found':\n      return new AuthorizedEntriesError('authorized-directory-not-found', 404)\n    case 'fnos-path-not-readable':\n    case 'fnos-user-permission-denied':\n      return new AuthorizedEntriesError('authorized-directory-not-readable', 403)\n    case 'fnos-user-permission-unavailable':\n      return new AuthorizedEntriesError('fnos-user-permission-check-unavailable', 503)\n    default:\n      return new AuthorizedEntriesError('fnos-path-not-authorized', 403)\n  }\n}\n\nfunction sortAuthorizedEntries(entries: AuthorizedEntry[]): AuthorizedEntry[] {\n  return entries.sort((left, right) => {\n    if (left.kind !== right.kind) return left.kind === 'directory' ? -1 : 1\n    return left.semanticPath.localeCompare(right.semanticPath, undefined, { numeric: true, sensitivity: 'base' })\n  })\n}\n\n/**\n * List only existing, readable authorized roots or one authorized directory\n * level. The app ACL root is only the first boundary: every returned entry is\n * also checked with the real filesystem and, when the request came through\n * the fnOS gateway, the current user's ACL.\n */\nexport async function loadAuthorizedEntries(\n  req: IncomingMessage,\n  pathValue?: string,\n): Promise<AuthorizedEntriesResponse> {\n  const roots = await resolvedAuthorizedRoots()\n  if (pathValue === undefined) {\n    const userAcl = await checkCurrentUserAcl(req, roots, roots)\n    if (!userAcl.available) {\n      throw new AuthorizedEntriesError('fnos-user-permission-check-unavailable', 503)\n    }\n    const readableRoots = roots.filter(root => userAcl.readable.has(root))\n    const readable = await convertPathsForDisplay(readableRoots, requestLanguage(req))\n    return {\n      entries: readable.map(entry => ({ ...entry, kind: 'directory' as const })),\n    }\n  }\n\n  const pathValidation = await validateReadableAuthorizedPath(req, pathValue, roots, checkCurrentUserAcl)\n  if (!pathValidation.ok) throw authorizedEntriesErrorForValidation(pathValidation)\n  const directoryStat = await stat(pathValue)\n  if (!directoryStat.isDirectory()) {\n    throw new AuthorizedEntriesError('authorized-path-not-directory', 400)\n  }\n\n  let children\n  try {\n    children = await readdir(pathValue, { withFileTypes: true })\n  } catch {\n    throw new AuthorizedEntriesError('authorized-directory-not-readable', 403)\n  }\n\n  const candidates: { path: string; kind: 'file' | 'directory'; size?: number; modifiedAt?: number }[] = []\n  for (const child of children) {\n    const childPath = normalizePathForAuthorization(posix.join(pathValue, child.name))\n    if (childPath === undefined) continue\n    try {\n      const childStat = await readablePathStat(childPath)\n      if (childStat === undefined) continue\n      if (!await isResolvedPathWithinAuthorizedRoots(childPath, roots)) continue\n      const candidate: { path: string; kind: 'file' | 'directory'; size?: number; modifiedAt?: number } = {\n        path: childPath,\n        kind: childStat.isDirectory() ? 'directory' : 'file',\n        modifiedAt: childStat.mtimeMs,\n      }\n      if (childStat.isFile()) candidate.size = childStat.size\n      candidates.push(candidate)\n    } catch {\n      // A disappearing or unreadable child should not make the whole picker\n      // unusable; the next refresh will reconcile it.\n    }\n  }\n\n  const userAcl = await checkCurrentUserAcl(req, candidates.map(entry => entry.path), roots)\n  if (!userAcl.available) {\n    throw new AuthorizedEntriesError('fnos-user-permission-check-unavailable', 503)\n  }\n  const readableCandidates = candidates.filter(entry => userAcl.readable.has(entry.path))\n  const truncated = readableCandidates.length > AUTHORIZED_ENTRIES_LIMIT\n  const selected = readableCandidates.slice(0, AUTHORIZED_ENTRIES_LIMIT)\n  const readable = await convertPathsForDisplay([pathValue, ...selected.map(entry => entry.path)], requestLanguage(req))\n  const readableByPath = new Map(readable.map(entry => [entry.path, entry.semanticPath]))\n  return {\n    directory: {\n      path: pathValue,\n      semanticPath: readableByPath.get(pathValue) ?? readableFallbackPath(pathValue, requestLanguage(req)),\n    },\n    entries: sortAuthorizedEntries(selected.map(entry => ({\n      ...entry,\n      semanticPath: readableByPath.get(entry.path) ?? readableFallbackPath(entry.path, requestLanguage(req)),\n    }))),\n    truncated,\n  }\n}\n\n/**\n * Path conversion is a display helper, not an authorization bypass. Reject\n * arbitrary or stale paths before returning their semantic names.\n */\nasync function validatePathsForConversion(req: IncomingMessage, paths: readonly string[]): Promise<string[]> {\n  const roots = await resolvedAuthorizedRoots()\n  const userAcl = await checkCurrentUserAcl(req, paths, roots)\n  if (!userAcl.available) {\n    throw new AuthorizedEntriesError('fnos-user-permission-check-unavailable', 503)\n  }\n  let failure: PathValidationFailure | undefined\n  for (const path of paths) {\n    let pathStat: Stats\n    try {\n      pathStat = await stat(path)\n    } catch {\n      failure ??= 'fnos-path-not-found'\n      continue\n    }\n    try {\n      const mode = pathStat.isDirectory() ? fsConstants.R_OK | fsConstants.X_OK : fsConstants.R_OK\n      await access(path, mode)\n    } catch {\n      failure ??= 'fnos-path-not-readable'\n      continue\n    }\n    if (!await isResolvedPathWithinAuthorizedRoots(path, roots)) {\n      failure ??= 'fnos-path-not-authorized'\n      continue\n    }\n    if (!userAcl.readable.has(path)) {\n      failure ??= 'fnos-user-permission-denied'\n    }\n  }\n  if (failure !== undefined) throw authorizedEntriesErrorForValidation({ ok: false, failure })\n  return [...paths]\n}\n\n/** Register fnOS settings/document and authorized-directory routes on the DSH Web profile. */\nexport function registerAuthorizedDirectoryRoutes(ctx: Context, options: { settingsNamespace?: string } = {}): void {\n  const settingsNamespace = options.settingsNamespace\n  ctx.effect(() => {    const authorize = (req: IncomingMessage, res: ServerResponse): boolean => {\n      if (isTrustedFnosRequest(req)) return true\n      json(res, 403, { error: 'remote-web-origin-not-trusted' })\n      return false\n    }\n    /**\n     * Register one fnOS route behind a last-resort rejection guard.\n     *\n     * The DSH webserver answers any rejection escaping a route handler with a\n     * bare empty `400`, which hides the cause from the browser and from the NAS\n     * log. Each handler below still reports its own precise status; this wrapper\n     * only makes a genuinely unexpected rejection diagnosable instead of blank.\n     */\n    const register = (route: {\n      kind: 'exact'\n      path: string\n      handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>\n    }): (() => void) => ctx.webServer.register({\n      ...route,\n      handler: (req, res) => Promise.resolve(route.handler(req, res)).catch((error: unknown) => {\n        console.error(`[dsh-fnos] route ${route.path} failed`, error)\n        if (res.headersSent || res.writableEnded || res.destroyed) return\n        json(res, 500, { error: 'fnos-route-failed' })\n      }),\n    })\n    const routes = [\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_DIRECTORIES_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            // 持久化列表优先：实时查询失败时仍要展示已保存的目录\n            // （FNOS-009-09-AC-02），所以这里带着持久化项一起加载。\n            const persisted = settingsNamespace === undefined\n              ? []\n              : readPersistedAuthorizedDirectories(\n                ctx.settings as unknown as AuthorizedDirectoriesSettings,\n                settingsNamespace,\n              )\n            const directories = await loadAuthorizedDirectoriesWithPersisted(req, persisted)\n            // 权限校验用无交互的查询接口，不逐个路径申请授权（FNOS-009-10）：\n            // 后者会给用户弹确认框，且返回值只说明「这次申请」的结果。\n            json(res, 200, { directories: markAuthorizedDirectoryValidity(directories, await knownAuthorizedPaths(req)) })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_SETTINGS_DOCUMENT_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'GET') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const path = await ctx.settings.prepareDocument()\n            if (path === undefined) return json(res, 404, { error: 'fnos-settings-document-unavailable' })\n            json(res, 200, { path })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_SESSION_LOG_EXPORT_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          // Everything from here on is inside one try: `readJsonBody` rejects on\n          // a malformed or oversized body and `validatePathForOpen` can reject\n          // while resolving authorized roots. Letting either escape would make\n          // the webserver answer a bare empty 400 instead of the JSON error the\n          // browser needs to explain the failure.\n          let request: FnosSessionLogExportRequest | undefined\n          try {\n            request = sessionLogExportRequest(await readJsonBody(req))\n          } catch {\n            return json(res, 400, { error: 'invalid-session-log-export-request' })\n          }\n          if (request === undefined) return json(res, 400, { error: 'invalid-session-log-export-request' })\n\n          let validation\n          try {\n            validation = await validatePathForOpen(request.directory, req)\n          } catch (error: unknown) {\n            errorResponse(res, error)\n            return\n          }\n          if (!validation.ok) {\n            const status = validation.failure === 'fnos-path-not-found' ? 404\n              : validation.failure === 'fnos-user-permission-unavailable' ? 503\n                : 403\n            return json(res, status, { error: validation.failure })\n          }\n          try {\n            const directoryStat = await stat(request.directory)\n            if (!directoryStat.isDirectory()) return json(res, 409, { error: 'fnos-session-log-target-not-directory' })\n            await access(request.directory, fsConstants.W_OK | fsConstants.X_OK)\n          } catch {\n            return json(res, 403, { error: 'fnos-session-log-target-not-writable' })\n          }\n\n          const abortController = new AbortController()\n          const abort = (): void => { abortController.abort() }\n          req.once('close', abort)\n          const target = posix.join(request.directory, sessionLogExportFilename(request.sessionId))\n          try {\n            const response = await fetchSessionLogZip(ctx, request.sessionId, abortController.signal, req.headers.cookie)\n            if (!response.ok) {\n              return json(res, response.status >= 400 && response.status < 500 ? response.status : 500, {\n                error: 'fnos-session-log-export-unavailable',\n              })\n            }\n            await writeSessionLogResponse(response, target, abortController.signal)\n            json(res, 201, { path: target })\n          } catch (error: unknown) {\n            if (!abortController.signal.aborted) {\n              console.error('[dsh-fnos] session log NAS export failed', error)\n              if (!res.writableEnded) json(res, 500, { error: 'fnos-session-log-export-failed' })\n            }\n          } finally {\n            req.off('close', abort)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_DIRECTORIES_DELETE_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const path = deletePath(await readJsonBody(req))\n            if (path === undefined) return json(res, 400, { error: 'invalid-authorized-directory-path' })\n            // 与 GET 用同一条合并逻辑：持久化项也在可移除范围内，否则用户\n            // 无法取消一个只存在于持久化记录里的目录。\n            const persisted = settingsNamespace === undefined\n              ? []\n              : readPersistedAuthorizedDirectories(\n                ctx.settings as unknown as AuthorizedDirectoriesSettings,\n                settingsNamespace,\n              )\n            const current = await loadAuthorizedDirectoriesWithPersisted(req, persisted)\n            const directory = current.find(candidate => candidate.path === path)\n            if (directory === undefined) {\n              return json(res, 409, { error: 'authorized-directory-not-found' })\n            }\n            if (!directory.removable) return json(res, 409, { error: 'authorized-directory-not-removable' })\n            const result = await callFnOsApi<SharedAccessibleFolderDeleteResult>(\n              'trim.file.delSharedAccessibleFolder',\n              { path },\n            )\n            if (result?.suc === false) return json(res, 502, { error: 'fnos-authorized-directory-request-failed' })\n            markAuthorizedPathRemoved(path)\n            json(res, 200, { ok: true })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      /**\n       * 持久化授权目录列表（FNOS-009-09）。\n       *\n       * 客户端在校验剔除后回写剩余项；这里只接受合法绝对路径，写入失败时\n       * 返回错误但**不清空**既有记录——遗留数据比丢数据安全（09-AC-03）。\n       */\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_DIRECTORIES_PERSIST_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          if (settingsNamespace === undefined) return json(res, 503, { error: 'fnos-authorized-directories-unavailable' })\n          try {\n            const paths = conversionPaths(await readJsonBody(req))\n            if (paths === undefined) return json(res, 400, { error: 'invalid-fnos-paths' })\n            const stored = await writePersistedAuthorizedDirectories(\n              ctx.settings as unknown as AuthorizedDirectoriesSettings,\n              settingsNamespace,\n              paths,\n            )\n            json(res, 200, { paths: stored })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_PATH_CONVERSION_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const paths = conversionPaths(await readJsonBody(req))\n            if (paths === undefined) return json(res, 400, { error: 'invalid-fnos-paths' })\n            const validPaths = await validatePathsForConversion(req, paths)\n            json(res, 200, { paths: await convertPathsForDisplay(validPaths, requestLanguage(req)) })\n          } catch (error: unknown) {\n            if (error instanceof AuthorizedEntriesError) {\n              json(res, error.status, { error: error.code })\n              return\n            }\n            errorResponse(res, error)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_PATH_OPEN_VALIDATION_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const path = openPathValue(await readJsonBody(req))\n            if (path === undefined) return json(res, 400, { error: 'invalid-fnos-path' })\n            const validation = await validatePathForOpen(path, req)\n            if (!validation.ok) {\n              const status = validation.failure === 'fnos-path-not-found' ? 404\n                : validation.failure === 'fnos-user-permission-unavailable' ? 503\n                  : 403\n              return json(res, status, { error: validation.failure })\n            }\n            json(res, 200, { ok: true })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_ENTRIES_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const path = listingPathValue(await readJsonBody(req))\n            if (path === null) return json(res, 400, { error: 'invalid-fnos-path' })\n            json(res, 200, await loadAuthorizedEntries(req, path))\n          } catch (error: unknown) {\n            if (error instanceof AuthorizedEntriesError) {\n              json(res, error.status, { error: error.code })\n              return\n            }\n            errorResponse(res, error)\n          }\n        },\n      }),\n      /**\n       * 在已授权目录内新建空目录或空文件（FNOS-034）。\n       *\n       * 授权校验与读取列表**共用**同一条路径：父目录必须真实存在、可读可进入、\n       * 落在授权根内，且当前 NAS 用户有权限。因此这条路由不会成为绕过授权的\n       * 写入缝隙。\n       *\n       * 不覆盖已存在条目：`wx` / `mkdir` 的排他语义保证并发下也只有一个成功，\n       * 已存在时返回 409 而不是静默覆盖用户数据。\n       */\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_CREATE_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const request = parseCreateRequest(await readJsonBody(req))\n            if (request === null) return json(res, 400, { error: 'invalid-fnos-create-request' })\n            const roots = await resolvedAuthorizedRoots()\n            const parentValidation = await validateReadableAuthorizedPath(req, request.parent, roots, checkCurrentUserAcl)\n            if (!parentValidation.ok) {\n              return json(res, authorizedEntriesErrorForValidation(parentValidation).status, {\n                error: authorizedEntriesErrorForValidation(parentValidation).code,\n              })\n            }\n            const target = normalizePathForAuthorization(posix.join(request.parent, request.name))\n            // 名字是单段且已排除分隔符，这里再确认一次落点仍在授权根内。\n            if (target === undefined || !isPathWithinAuthorizedDirectory(target, roots)) {\n              return json(res, 403, { error: 'fnos-path-not-authorized' })\n            }\n            try {\n              if (request.kind === 'directory') await mkdir(target)\n              else await writeFile(target, '', { flag: 'wx' })\n            } catch (error: unknown) {\n              const code = (error as { code?: unknown }).code\n              if (code === 'EEXIST') return json(res, 409, { error: 'fnos-entry-exists' })\n              if (code === 'EACCES' || code === 'EPERM') return json(res, 403, { error: 'fnos-create-permission-denied' })\n              if (code === 'ENOSPC' || code === 'EDQUOT') return json(res, 507, { error: 'fnos-create-no-space' })\n              if (code === 'EROFS') return json(res, 403, { error: 'fnos-create-read-only' })\n              throw error\n            }\n            const entry: AuthorizedEntry = {\n              path: target,\n              semanticPath: (await convertPathsForDisplay([target], requestLanguage(req)))[0]?.semanticPath ?? target,\n              kind: request.kind,\n            }\n            json(res, 200, { entry } satisfies AuthorizedCreateResponse)\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      /**\n       * 删除授权目录内的一个条目（FNOS-034）。\n       *\n       * 破坏性操作，但边界与读取、新建一致：目标必须落在授权根内。额外加一条\n       * **硬约束**：授权根本身不允许删除——用户删掉根等于把应用的数据目录整个\n       * 抹掉，那不该由这个面板触发。\n       */\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_DELETE_ENTRY_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const request = parseDeleteRequest(await readJsonBody(req))\n            if (request === null) return json(res, 400, { error: 'invalid-fnos-delete-request' })\n            const roots = await resolvedAuthorizedRoots()\n            if (!isPathWithinAuthorizedDirectory(request.path, roots)) {\n              return json(res, 403, { error: 'fnos-path-not-authorized' })\n            }\n            // 授权根本身不可删：比对规范化后的根集合，避免用 `..` 或尾斜杠绕过。\n            if (roots.some(root => normalizePathForAuthorization(root) === request.path)) {\n              return json(res, 403, { error: 'fnos-delete-root-forbidden' })\n            }\n            const entryStat = await stat(request.path).catch(() => undefined)\n            if (entryStat === undefined) return json(res, 404, { error: 'fnos-entry-not-found' })\n            try {\n              // 目录递归删除；文件只需 unlink 语义，`recursive` 对文件同样成立。\n              await rm(request.path, { recursive: entryStat.isDirectory(), force: false })\n            } catch (error: unknown) {\n              const code = (error as { code?: unknown }).code\n              if (code === 'EACCES' || code === 'EPERM') return json(res, 403, { error: 'fnos-delete-permission-denied' })\n              if (code === 'ENOTEMPTY') return json(res, 409, { error: 'fnos-delete-not-empty' })\n              if (code === 'EROFS') return json(res, 403, { error: 'fnos-delete-read-only' })\n              if (code === 'EBUSY') return json(res, 409, { error: 'fnos-delete-busy' })\n              throw error\n            }\n            json(res, 200, { ok: true })\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n      /**\n       * 重命名授权目录内的一个条目（文件或目录）。\n       *\n       * 边界与新建/删除一致：目标必须落在授权根内。额外两条：\n       *\n       * 1. 授权根本身不可改名——授权记录按路径登记，改名会让已持久化的记录\n       *    指向一个不存在的路径。\n       * 2. 目标名已存在时直接报错，不覆盖。POSIX 的 `rename` 会静默覆盖同名\n       *    文件，那等于用一个改名动作销毁了另一份用户数据。\n       */\n      register({\n        kind: 'exact',\n        path: FNOS_AUTHORIZED_RENAME_ENTRY_PATH,\n        handler: async (req, res) => {\n          if (req.method !== 'POST') return json(res, 405, { error: 'method not allowed' })\n          if (!authorize(req, res)) return\n          try {\n            const request = parseRenameRequest(await readJsonBody(req))\n            if (request === null) return json(res, 400, { error: 'invalid-fnos-rename-request' })\n            const roots = await resolvedAuthorizedRoots()\n            if (!isPathWithinAuthorizedDirectory(request.path, roots)) {\n              return json(res, 403, { error: 'fnos-path-not-authorized' })\n            }\n            if (roots.some(root => normalizePathForAuthorization(root) === request.path)) {\n              return json(res, 403, { error: 'fnos-rename-root-forbidden' })\n            }\n            const entryStat = await stat(request.path).catch(() => undefined)\n            if (entryStat === undefined) return json(res, 404, { error: 'fnos-entry-not-found' })\n            const kind: AuthorizedCreateKind = entryStat.isDirectory() ? 'directory' : 'file'\n            const target = normalizePathForAuthorization(posix.join(posix.dirname(request.path), request.name))\n            if (target === undefined || !isPathWithinAuthorizedDirectory(target, roots)) {\n              return json(res, 403, { error: 'fnos-path-not-authorized' })\n            }\n            const semanticPathFor = async (path: string): Promise<string> =>\n              (await convertPathsForDisplay([path], requestLanguage(req)))[0]?.semanticPath ?? path\n            // 名字没变：不调用文件系统，直接把当前条目回给调用方。\n            if (target === request.path) {\n              json(res, 200, { entry: { path: target, semanticPath: await semanticPathFor(target), kind } } satisfies AuthorizedRenameResponse)\n              return\n            }\n            const existing = await stat(target).catch(() => undefined)\n            if (existing !== undefined) return json(res, 409, { error: 'fnos-entry-exists' })\n            try {\n              await rename(request.path, target)\n            } catch (error: unknown) {\n              const code = (error as { code?: unknown }).code\n              if (code === 'EACCES' || code === 'EPERM') return json(res, 403, { error: 'fnos-rename-permission-denied' })\n              if (code === 'EROFS') return json(res, 403, { error: 'fnos-rename-read-only' })\n              if (code === 'ENOENT') return json(res, 404, { error: 'fnos-entry-not-found' })\n              if (code === 'EEXIST' || code === 'ENOTEMPTY') return json(res, 409, { error: 'fnos-entry-exists' })\n              if (code === 'EBUSY') return json(res, 409, { error: 'fnos-rename-busy' })\n              throw error\n            }\n            json(res, 200, { entry: { path: target, semanticPath: await semanticPathFor(target), kind } } satisfies AuthorizedRenameResponse)\n          } catch (error: unknown) {\n            errorResponse(res, error)\n          }\n        },\n      }),\n    ]\n    return () => {\n      for (const dispose of routes) dispose()\n    }\n  }, 'dsh-fnos: authorized directory routes')\n}\n"
    },
    {
      "path": "plugins/dsh-fnos-plugin/src/client/services/theme-controller.ts",
      "content": "/** Synchronizes fnOS's resolved theme while DSH follows its system preference. */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport { isDshThemePreference } from '../../host/theme-bootstrap.ts'\nimport type { ThemeBridge } from './theme-bridge.ts'\nimport type { createThemePersistence } from './theme-persistence.ts'\n\nconst DARK_ATTRIBUTE = 'data-ds-dark-theme'\n\n/**\n * Keep DSH's explicit preferences authoritative. The fnOS theme is only a\n * temporary projection for the `system` preference and must not win a later\n * DSH light/dark selection because of listener ordering.\n */\nexport function createThemeController(\n  ctx: ClientContext,\n  bridge: ThemeBridge,\n  persistence: ReturnType<typeof createThemePersistence>,\n) {\n  let systemFallbackActive = false\n  let previousColorScheme: string | undefined\n  let previousDarkAttribute: boolean | undefined\n\n  const applySystemTheme = (theme: 'light' | 'dark'): void => {\n    if (typeof document === 'undefined') return\n    if (!systemFallbackActive) {\n      previousColorScheme = document.documentElement.style.colorScheme\n      previousDarkAttribute = document.body?.hasAttribute(DARK_ATTRIBUTE)\n    }\n    const dark = theme === 'dark'\n    document.documentElement.style.colorScheme = dark ? 'dark' : 'light'\n    document.body?.toggleAttribute(DARK_ATTRIBUTE, dark)\n    systemFallbackActive = true\n  }\n\n  const clearSystemTheme = (restorePrevious: boolean): void => {\n    if (systemFallbackActive && restorePrevious && typeof document !== 'undefined') {\n      if (previousColorScheme === '') document.documentElement.style.removeProperty('color-scheme')\n      else if (previousColorScheme !== undefined) document.documentElement.style.colorScheme = previousColorScheme\n      if (previousDarkAttribute === true) document.body?.setAttribute(DARK_ATTRIBUTE, '')\n      else if (previousDarkAttribute === false) document.body?.removeAttribute(DARK_ATTRIBUTE)\n    }\n    previousColorScheme = undefined\n    previousDarkAttribute = undefined\n    systemFallbackActive = false\n  }\n\n  const refresh = (): void => {\n    const theme = ctx.theme\n    const preference = theme.getTheme().preference\n    if (preference !== 'system') {\n      if (isDshThemePreference(preference)) persistence.sync(preference, null)\n      // DSH's ThemePresenter owns explicit light/dark DOM state. Do not\n      // restore the state captured before the temporary system projection.\n      clearSystemTheme(false)\n      return\n    }\n\n    const fnosTheme = bridge.getTheme()\n    persistence.sync(preference, fnosTheme)\n    if (fnosTheme === null) return\n\n    applySystemTheme(fnosTheme)\n    // DSH's ThemePresenter also listens to theme/change. Re-apply after the\n    // current event turn so the fnOS state wins regardless of listener order.\n    queueMicrotask(() => {\n      if (ctx.theme.getTheme().preference === 'system' && bridge.getTheme() === fnosTheme) {\n        applySystemTheme(fnosTheme)\n      }\n    })\n  }\n\n  return {\n    refresh,\n    dispose(): void {\n      clearSystemTheme(true)\n    },\n  }\n}\n"
    },
    {
      "path": "plugins/dsh-fnos-plugin/src/client/services/sdk-carrier.ts",
      "content": "/** Browser-host detection shared without importing the browser SDK module. */\n\nexport function isEmbeddedFnosFrame(): boolean {\n  return typeof window !== 'undefined' && window.parent !== window\n}\n\nexport function shouldForceWebCarrier(userAgent: string, embedded: boolean): boolean {\n  return embedded && /FNAppVer\\//iu.test(userAgent)\n}\n"
    },
    {
      "path": "plugins/dsh-fnos-plugin/src/client/index.ts",
      "content": "/** Browser half of the fnOS-specific DSH integration plugin. */\n\nimport '../styles/index.scss'\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-api-remotes/client'\nimport type { SessionId } from '@deepseek-ai/dsh-session/types'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type { FnosLocaleKey } from './locales.ts'\nimport type { ReferenceInsert, SessionInput } from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport type { CommandUiContract } from '@deepseek-ai/dsh-client-ui-commands/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-commands/client'\nimport type { InputTriggerServiceContract, InputTriggerSource } from '@deepseek-ai/dsh-client-ui-input-trigger/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\n// Type-only: 拉入插件管理页对 `plugins.detail.section` 的登记契约\n// （`PluginDetailProps`）。该包只在类型层使用，运行时不 import——客户端模块表\n// 里没有它，运行时引入会直接报模块缺失。\nimport type {} from '@deepseek-ai/dsh-client-ui-plugin-manager/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\n// Type-only: 拉入 ui-session 对 GlobalStandardProps/SessionStandardProps 的合并\n// （useSessions、sessionId、useProjection），会话作用域座位的标准套件才有类型。\nimport type {} from '@deepseek-ai/dsh-client-ui-session/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-theme/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-workspace/client'\nimport { AuthorizedDirectoriesDetailSection } from '../components/AuthorizedDirectoriesCard.tsx'\nimport type { FnosDetailSubject } from '../components/AuthorizedDirectoriesCard.tsx'\nimport { FnosInputPickerButton } from '../components/FnosInputPickerButton.tsx'\nimport { FnosAuthorizedPathPanel } from '../components/FnosAuthorizedPathPicker.tsx'\nimport { FnosOpenInHeaderAction } from '../components/FnosOpenInHeaderAction.tsx'\nimport { FnosSessionLogHeaderAction } from '../components/FnosSessionLogHeaderAction.tsx'\nimport { FNOS_OPEN_IN_APP_SEAT, FNOS_SESSION_LOG_SEAT } from './header-utility-seats.ts'\nimport { createPickerOpenStore } from './input-references/picker-store.ts'\nimport { insertFnosReferences } from './input-references/input-reference-actions.ts'\nimport { createFnosCommandContribution, createFnosDirectorySource } from './input-references/fnos-command-source.ts'\nimport { FNOS_REFERENCE_SOURCE, fnosReferenceDisplayText, fnosReferencePromptText, type FnosInputReference, type InputSnapshotForReference } from './input-references/input-references.ts'\nimport { en, zh } from './locales.ts'\nimport { installFnosRemotePathOpener } from './services/path-opener.ts'\nimport { installFnosPresentedOpen } from './services/present-open.ts'\nimport { FnosSettingsDocumentAction } from '../components/FnosSettingsDocumentAction.tsx'\nimport { FnosWebRestartAction } from '../components/FnosWebRestartAction.tsx'\nimport { installFnosBrowserRefreshShortcut } from './shortcuts/browser-refresh-shortcut.ts'\nimport { installFnosSettingsShortcut } from './shortcuts/settings-shortcut.ts'\nimport { isEmbeddedFnosFrame } from './services/sdk-carrier.ts'\nimport { createTrimApp } from './services/sdk.ts'\nimport { installFnosPageTitle } from './services/sdk-title.ts'\nimport { createThemeBridge } from './services/theme-bridge.ts'\nimport { createThemePersistence } from './services/theme-persistence.ts'\nimport { createThemeController } from './services/theme-controller.ts'\nimport { installWorkspaceAuthorizedShortcut } from './shortcuts/workspace-authorized-shortcut.ts'\nimport type { FnosSettings } from '../contracts/theme-contract.ts'\nimport { installSemiDshTheme } from '@tnnevol/dsh-semi-ui'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    'settings.dsh-fnos': FnosLocaleKey\n  }\n}\n\nexport const name = 'dsh-fnos-plugin-client'\nexport const inject = ['theme', 'slots', 'locale', 'sessions', 'inputTriggers', 'commandUi', 'remote', 'remote.session', 'configForms', 'sessionLogDownload']\n\ntype SessionLogDownloadState = {\n  bySession: Record<string, { open: boolean, status: 'downloading' | 'success' | 'error', error: string | null } | undefined>\n}\n\ntype SessionLogDownloadStore = {\n  getSnapshot: () => SessionLogDownloadState\n  subscribe: (listener: () => void) => () => void\n}\n\ntype SessionLogDownloadController = {\n  store: SessionLogDownloadStore\n  download: (sessionId: SessionId) => Promise<void>\n  dismiss: (sessionId: SessionId) => void\n}\n\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => installSemiDshTheme(), 'dsh-fnos: Semi DSH theme')\n  const bridge = createThemeBridge()\n  const fnosSettings = ctx.configForms.get<FnosSettings>('dsh-fnos')\n  {\n    const controller = createThemeController(ctx, bridge, createThemePersistence(fnosSettings))\n\n    ctx.effect(() => {\n      const unsubscribe = bridge.subscribe(() => { controller.refresh() })\n      const unsubscribeSettings = fnosSettings.subscribe(() => { controller.refresh() })\n      const offThemeChange = ctx.on('theme/change', () => { controller.refresh() })\n      controller.refresh()\n      void bridge.connect().catch(error => {\n        console.debug('[dsh-fnos] unable to connect to fnOS theme events', error)\n      })\n\n      return async () => {\n        unsubscribe()\n        unsubscribeSettings()\n        offThemeChange()\n        await bridge.disconnect()\n        controller.dispose()\n      }\n    }, 'dsh-fnos: fnOS theme bridge')\n  }\n\n  const namespace = 'settings.dsh-fnos'\n  ctx.effect(() => ctx.locale.register(namespace, { zh, en }), 'dsh-fnos: locale')\n  const t = ctx.locale.bind(namespace) as (key: FnosLocaleKey) => string\n\n  ctx.effect(() => installFnosRemotePathOpener(ctx.remote.session, {\n    createSdk: createTrimApp,\n    message: key => t(key),\n  }), 'dsh-fnos: fnOS path opener')\n  ctx.effect(() => installFnosPageTitle(createTrimApp), 'dsh-fnos: fnOS page title')\n  ctx.effect(() => installFnosBrowserRefreshShortcut(), 'dsh-fnos: browser refresh shortcut')\n  ctx.effect(() => installFnosSettingsShortcut(), 'dsh-fnos: settings shortcut')\n  ctx.effect(() => installWorkspaceAuthorizedShortcut(t), 'dsh-fnos: workspace authorized shortcut')\n\n  const source: InputTriggerSource = {\n    trigger: '@',\n    name: FNOS_REFERENCE_SOURCE,\n    candidates: async () => [],\n    onPick: () => undefined,\n    codec: {\n      clipboardText: ref => fnosReferencePromptText(ref),\n      serialize: async ref => fnosReferencePromptText(ref),\n    },\n  }\n  const directorySource = createFnosDirectorySource(t)\n  const inputTriggers = ctx.get('inputTriggers') as InputTriggerServiceContract\n  ctx.effect(() => {\n    const unregister = inputTriggers.registerSource(source)\n    const unregisterDirectorySource = inputTriggers.registerSource(directorySource)\n    return () => {\n      unregisterDirectorySource()\n      unregister()\n    }\n  }, 'dsh-fnos: fnOS input reference source')\n\n  ctx.inject(['commandUi'], (scope: ClientContext) => {\n    const commandUi = scope.get('commandUi') as CommandUiContract\n    scope.effect(() => commandUi.register(createFnosCommandContribution(\n      t,\n      (sessionId, reference) => insertFnosCommandReference(ctx, sessionId, reference),\n    )), 'dsh-fnos: /fn command contribution')\n  })\n\n  if (isEmbeddedFnosFrame()) {\n    ctx.effect(() => installFnosPresentedOpen(createTrimApp), 'dsh-fnos: presented-file opener')\n    ctx.slots.inject('conversation.session.header.utilities', () => {\n      const sessionLogDownload = ctx.get('sessionLogDownload') as SessionLogDownloadController | undefined\n      if (sessionLogDownload === undefined) throw new Error('sessionLogDownload service is unavailable')\n      return ctx.slots.register({\n        ...FNOS_SESSION_LOG_SEAT,\n        locale: namespace,\n        inject: (sessionId) => ({\n          hooks: { sessionLogDownload: sessionLogDownload.store },\n          sessionId,\n          exportToComputer: (sessionId: SessionId) => sessionLogDownload.download(sessionId),\n          dismissDownload: (sessionId: SessionId) => { sessionLogDownload.dismiss(sessionId) },\n        }),\n      }, FnosSessionLogHeaderAction)\n    })\n    // 遮蔽 DSH 官方的「打开应用」按钮（同 id、更低 priority，低者生效）。\n    //\n    // 官方按钮按编译期常量表探测本机应用，在 fnOS 上会把系统的 ZFS Event\n    // Daemon（`/usr/sbin/zed`）误判为 Zed 编辑器，且取不到对应图标，菜单里\n    // 因此出现一个点了也打不开编辑器的条目。该常量表不可配置，所以在这里用\n    // fnOS 自己的文件能力替代它。只改 fnOS iframe 内的表现。\n    // 排序（priority 升序、再 order 升序）与遮蔽规则的取值集中在\n    // `header-utility-seats.ts`，并由测试用真实 SlotCore 驱动验证实际顺序。\n    ctx.slots.inject('conversation.session.header.utilities', () => ctx.slots.register({\n      ...FNOS_OPEN_IN_APP_SEAT,\n      locale: namespace,\n      inject: () => ({ t }),\n    }, FnosOpenInHeaderAction))\n    ctx.slots.inject('settings.action', () => ctx.slots.register({\n      name: 'settings.action',\n      id: 'open-document',\n      order: 0,\n      priority: -1,\n      locale: namespace,\n      inject: () => ({ t }),\n    }, FnosSettingsDocumentAction))\n  }\n  /**\n   * 授权目录配置块挂在插件管理页的 fnOS 组合包详情页。\n   *\n   * 座位选 `plugins.detail.section` 而不是官方的 `plugins.bundle.config`：上游\n   * `PackageDetail` 的固定顺序是\n   *\n   *   1. `plugins.bundle.config`（组合包自己的配置）\n   *   2. 「包含的组件」（`RowsSection`）\n   *   3. `plugins.detail.section`（本座位）\n   *\n   * 需求要求配置块在「包含的组件」**之后**，只有 3 满足。\n   *\n   * 代价是该座位是 **list**（非 keyed）：页面会给打开的每个详情页渲染它，因此\n   * 组件必须自己看 `subject`——不是本插件就返回 `null`（见\n   * `AuthorizedDirectoriesDetailSection`）。list 座位要求 `id`，且不能声明\n   * `inject`（owner props 由页面传入）。\n   */\n  ctx.slots.inject('plugins.detail.section', () => ctx.slots.register({\n    name: 'plugins.detail.section',\n    id: 'dsh-fnos-authorized-directories',\n    order: 40,\n    locale: namespace,\n  }, (props: { subject?: FnosDetailSubject | undefined }) =>\n    // 本文件是 `.ts`（无 JSX），因此用调用而不是